<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { api, patch, post } from '../api';
import { dateTime, label } from '../format';

const items = ref<any[]>([]); const groups = ref<any[]>([]); const loading = ref(false); const error = ref('');
const showCreate = ref(false); const activationCode = ref(''); const createdEmployeeNo = ref('');
const form = ref({ employeeNo: '', name: '', role: 'NURSE', primaryGroupId: '' });
const bulk = ref(''); const showBulk = ref(false);

async function load() { loading.value = true; try { const [users, groupResult] = await Promise.all([api('/users?pageSize=100'), api('/groups')]); items.value = users.items; groups.value = groupResult.items ?? groupResult; } catch (cause: any) { error.value = cause.message; } finally { loading.value = false; } }
async function create() { try { const user = await post('/users', { ...form.value, primaryGroupId: form.value.primaryGroupId || null }); const code = await post(`/users/${user.id}/activation-codes`, { purpose: 'ACTIVATE_ACCOUNT', reason: '新增人员首次激活' }); activationCode.value = code.activationCode; createdEmployeeNo.value = user.employeeNo; showCreate.value = false; form.value = { employeeNo: '', name: '', role: 'NURSE', primaryGroupId: '' }; await load(); } catch (cause: any) { alert(cause.message); } }
async function disable(user: any) { const reason = prompt(`请输入停用 ${user.name} 的原因`); if (!reason) return; try { await patch(`/users/${user.id}`, { status: 'DISABLED', reason }); await load(); } catch (cause: any) { alert(cause.message); } }
async function reset(user: any) { try { const code = await post(`/users/${user.id}/activation-codes`, { purpose: 'RESET_PASSWORD', reason: '管理员发起密码重置' }); activationCode.value = code.activationCode; createdEmployeeNo.value = user.employeeNo; } catch (cause: any) { alert(cause.message); } }
async function importRows() { const rows = bulk.value.split(/\r?\n/).map((line) => line.trim()).filter(Boolean).map((line) => { const [employeeNo, name, role = 'NURSE'] = line.split(',').map((part) => part.trim()); return { employeeNo, name, role }; }); if (!rows.length) return; try { const result = await post('/users/import', { rows }); alert(`导入完成：成功 ${result.successCount ?? result.results?.filter((row: any) => row.success).length ?? 0} 条`); showBulk.value = false; bulk.value = ''; await load(); } catch (cause: any) { alert(cause.message); } }
async function createGroup() { const code = prompt('请输入分组代码'); if (!code) return; const name = prompt('请输入分组名称'); if (!name) return; try { await post('/groups', { code, name, enabled: true }); await load(); } catch (cause: any) { alert(cause.message); } }
onMounted(load);
</script>

<template>
  <div class="page-head"><div><h3>人员与账号</h3><span class="muted">账号预建、激活、停用和护理分组</span></div><div class="page-actions"><button class="secondary" @click="createGroup">新增分组</button><button class="secondary" @click="showBulk = true">批量导入</button><button class="primary" @click="showCreate = true">＋ 新增人员</button></div></div>
  <section class="panel"><p v-if="error" class="form-error">{{ error }}</p><div v-if="loading" class="empty">正在加载…</div><div v-else class="table-wrap"><table class="data-table"><thead><tr><th>姓名 / 工号</th><th>角色</th><th>状态</th><th>护理分组</th><th>激活时间</th><th>操作</th></tr></thead><tbody><tr v-for="user in items" :key="user.id"><td><strong>{{ user.name }}</strong><small style="display:block;color:#698087">{{ user.employeeNo }}</small></td><td>{{ label(user.role) }}</td><td><span :class="['tag', user.status === 'ACTIVE' ? 'success' : 'neutral']">{{ label(user.status) }}</span></td><td>{{ groups.find((group:any) => group.id === user.primaryGroupId)?.name ?? '—' }}</td><td>{{ dateTime(user.activatedAt) }}</td><td><div class="inline-actions"><button v-if="['ACTIVE','LOCKED'].includes(user.status)" class="ghost small-button" @click="reset(user)">重置密码</button><button v-if="user.role !== 'HEAD_NURSE' && user.status !== 'DISABLED'" class="danger small-button" @click="disable(user)">停用</button></div></td></tr></tbody></table></div></section>
  <div v-if="showCreate" class="modal-backdrop"><form class="modal" @submit.prevent="create"><div class="modal-head"><h3>新增人员</h3><button type="button" @click="showCreate = false">×</button></div><div class="form-grid"><label class="field">工号<input v-model="form.employeeNo" required /></label><label class="field">姓名<input v-model="form.name" required /></label><label class="field">角色<select v-model="form.role"><option value="NURSE">护士</option><option value="COORDINATOR">协管员</option><option value="HEAD_NURSE">护士长</option></select></label><label class="field">护理分组<select v-model="form.primaryGroupId"><option value="">暂不分组</option><option v-for="group in groups" :key="group.id" :value="group.id">{{ group.name }}</option></select></label></div><div class="page-actions" style="margin-top:20px;justify-content:flex-end"><button type="button" class="secondary" @click="showCreate = false">取消</button><button class="primary">创建并生成激活码</button></div></form></div>
  <div v-if="showBulk" class="modal-backdrop"><form class="modal" @submit.prevent="importRows"><div class="modal-head"><h3>批量导入人员</h3><button type="button" @click="showBulk = false">×</button></div><p class="muted">每行格式：工号,姓名,角色。角色可填写 NURSE、COORDINATOR 或 HEAD_NURSE。</p><textarea v-model="bulk" style="width:100%;min-height:240px" placeholder="N001,张护士,NURSE"></textarea><div class="page-actions" style="margin-top:20px;justify-content:flex-end"><button type="button" class="secondary" @click="showBulk = false">取消</button><button class="primary">开始导入</button></div></form></div>
  <div v-if="activationCode" class="modal-backdrop"><div class="modal"><div class="modal-head"><h3>一次性验证码</h3><button @click="activationCode = ''">×</button></div><p>工号：<b>{{ createdEmployeeNo }}</b></p><div class="code-box">{{ activationCode }}</div><p class="muted">验证码仅展示一次，有效期 24 小时，请通过安全方式转交本人。</p><button class="primary wide" @click="activationCode = ''">我已妥善记录</button></div></div>
</template>
